CREATE TABLE `food_records` (
  `food_id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `food_name` varchar(100) DEFAULT NULL,
  `carbs_grams` float DEFAULT NULL,
  `weight_grams` float DEFAULT NULL,
  `serving_count` float DEFAULT NULL,
  `peak_glucose` int DEFAULT NULL,
  `image_url` varchar(500) DEFAULT NULL,
  `memo` text,
  `meal_type` enum('BREAKFAST','LUNCH','DINNER','SNACK') DEFAULT NULL,
  `eaten_at` timestamp NULL DEFAULT NULL,
  `ai_guide` text,
  `recorded_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`food_id`),
  KEY `idx_food_user_time` (`user_id`,`recorded_at`),
  CONSTRAINT `fk_food_records_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`user_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1865 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
